а создания объекта пациента'); return false; } $this->initPractitionerXMLbase($practitionerObj); if (empty($this->practitionerXml)) { $this->log('Ошибка создания xml врача'); return false; } $authDataByGuid = $this->getAuthDataByReceipt($recipeCode, $recipeType); if (!$this->getAuth($authDataByGuid)) { $this->log('Ошибка при получении токена авторизации'); return false; } $patientObj = $this->createPatientObj($patientCode); if (!$patientObj) { $this->log('Ошибка создания объекта пациента'); return false; } $this->initPatientXMLbase($patientObj); if (empty($this->patientXml)) { $this->log('Ошибка создания xml пациента'); return false; } if ($this->syncPractitioner($practitionerObj)) { $syncResult = $this->syncPatient($patientObj); if ($syncResult === true) { $dbRecipe = $this->getDbRecipe($recipeCode, $recipeType); if (empty($dbRecipe)) { $this->log('Рецепт type: ' . $recipeType . ' id: ' . $recipeCode . ' не найден'); return false; } $recipeObj = $this->createRecipeObj($dbRecipe, $recipeType, $practitionerObj, $patientObj); if (empty($recipeObj)) { $this->log('Ошибка создания объекта рецепта'); return false; } $this->initSignRecipeXMLbase($recipeObj); if (empty($this->recipeXml)) { $this->log('Ошибка создания xml рецепта'); return false; } $result = new stdClass(); $result->sign = substr($this->recipeXml->asXML(), 22); $result->sign = html_entity_decode($result->sign); $result->sign = str_replace('"/', '" /', $result->sign); $result->sign = trim($result->sign); $this->recipeXml = null; $this->initRecipeXMLbase($recipeObj); if (empty($this->recipeXml)) { $this->log('Ошибка создания xml рецепта'); return false; } $result->signedContent = substr($this->recipeXml->asXML(), 22); $result->signedContent = html_entity_decode($result->signedContent); $result->signedContent = str_replace('"/', '" /', $result->signedContent); $result->signedContent = trim($result->signedContent); $this->log($result->sign); $this->log($result->signedContent); return $result; } else { $this->log('Ошибка синхронизации пациента'); return $this->errorResult(is_string($syncResult) ? $syncResult : 'Ошибка синхронизации пациента'); } } else { $this->log('Ошибка синхронизации врача'); return false; } } public function getAuthDataByReceipt($recipeCode, $recipeType) { $db = $this->db ?: $this->db = connectDb(); $tablePk = $recipeType . 'Code'; $sql = <<<"EOT"
