) { $dpcRecipe = new SimpleXMLElement($dpcRecipe); } $versionGUID = $this->xml_attribute($this->getXmlNode($dpcRecipe, 'versionId'), 'value'); $dbRecipeXml = new SimpleXMLElement('<?xml version="1.0" encoding="utf-8"?>' . $recipeObj->signedContent); $pNode = $dbRecipeXml->addChild('meta'); $this->xmlAddNodeEx($pNode, 'versionId', 'value', $versionGUID); $params = str_replace('"/', '" /', html_entity_decode($dbRecipeXml->asXML())); $recipe = $this->updateRecipeWithoutSign2DPC($recipeObj->GUID, $params); } else if (!empty($recipeObj->GUID) && $recipeObj->status == 'entered-in-error' && safe_strtotime($recipeObj->outDate) >= safe_strtotime('2020-07-27')) { $recipe = $this->deleteRecipeFromDPC($recipeObj->GUID); } if ($recipe) { $recipe = new SimpleXMLElement($recipe); $GUID = $this->xml_attribute($this->getXmlNode($recipe, 'id'), 'value'); $this->dbRecipe = $dbRecipe; $this->updateDbRecipe($GUID, $recipeType); return true; } else { return false; } } private function deleteRecipeFromDPC($GUID) { $request = new stdClass(); $request->url = $this->urlDPC . 'MedicationPrescription/' . $GUID . '/$set-as-error'; $request->headers['Authorization'] = "Bearer " . $this->authToken; $request->headers['Content-Type'] = "text/xml"; $request->headers['Accept'] = "application/xml+fhir"; $request->proxy = $this->getProxySettings(); $request->debug = self::DEBUG_HTTP; $result = httpPOST($request); switch ($result['status'][1]) { case "200": return $result['body']; default: $this->log('При отправке рецепта в ЦОД произошла ошибка: ' . print_r($result['body'], true)); return false; } } private function getEnterprise() { $db = $this->db ?: $this->db = connectDb(); $enterpriseCode = getSessionValue('mapEnterpriseCode') ?: 1; $sql = <<<"EOT"
