titionerObj->GUID) || $practitionerObj->state == 1) { if (empty($practitionerObj->GUID)) { $newDoctor = $this->addPractitioner(); if ($newDoctor) { $newDoctor = new SimpleXMLElement($newDoctor); $practitionerObj->GUID = $this->xml_attribute($this->getXmlNode($newDoctor, 'id'), 'value'); } else { $this->log('ошибка получения GUID регистрации в ЦОД врача, ФИО ' . $practitionerObj->FIO . ' key: ' . $practitionerObj->id); return false; } if (empty($practitionerObj->GUID)) { $this->log('Ошибка добавления врача в ЦОД'); return false; } $this->dbUpdateDoctorGUID($practitionerObj); return true; } else { $doctor = $this->getPractitioner($practitionerObj); if ($doctor) { $doctor = new SimpleXMLElement($doctor); $practitionerObj->versionGUID = $this->xml_attribute($this->getXmlNode($doctor, 'versionId'), 'value'); if (!empty($practitionerObj->versionGUID)) { $this->initPractitionerXMLbase($practitionerObj); if ($this->putPractitioner($practitionerObj)) { $this->dbUpdateDoctorGUID($practitionerObj); } else { $this->log('Произошла ошибка при обновлении врава c id' . $practitionerObj->id . ' в ЦОД'); } return true; } else { return false; } } else { $this->log('Попытка повторной регистрации в ЦОД врачаб ФИО ' . $practitionerObj->FIO . ' key: ' . $practitionerObj->id); $practitionerObj->GUID = ''; $practitionerObj->versionGUID = ''; $this->initPractitionerXMLbase($practitionerObj); $this->addPractitioner(); $this->log('Повторно зарегистрирован в ЦОД врач, ФИО ' . $practitionerObj->FIO . ' key: ' . $practitionerObj->id); return true; } } } return true; } private function syncPatient($patientObj) { if (empty($patientObj->GUID) || $patientObj->state = 1) { if (empty($patientObj->GUID)) { $this->addNewPatient($patientObj); } else { $DPCPatient = $this->getDPCPatientByGUID($patientObj); if (!$DPCPatient) { $this->log('попытка повторной регистрации в ЦОД пациента, а/к' . $patientObj->numberHistory); $patientObj->GUID = ''; $patientObj->versionGUID = ''; $this->initPatientXMLbase($patientObj); $this->addNewPatient($patientObj); $this->log('Повторно зарегистрирован в ЦОД пациент, а/к ' . $patientObj->numberHistory); } else { $DPCPatient = new SimpleXMLElement($DPCPatient); $patientObj->versionGUID = $this->xml_attribute($this->getXmlNode($DPCPatient, 'versionId'), 'value'); if (!empty($patientObj->versionGUID)) { $prevBarCode = $this->xmlGetPatientIdentifier($DPCPatient, self::ID_url_Bar); if ($prevBarCode != $patientObj->barCode) { $this->log('в ЦОД обнаружен неактивный НИКМО ' . $prevBarCode . ' у пациента, а/к ' . $patientObj->numberHistory); $patientObj->GUID = ''; $patientObj->versionGUID = ''; $this->initPatientXMLbase($patientObj); $this->addNewPatient($patientObj); $this->log('пациент заново добавлен в ЦОД с НИКМО '); } else { $patientObj->active = $this->xml_attribute($this->getXmlNode($DPCPatient, 'active'), 'value'); if ($patientObj->active !== 'true') { $this->log('Карта ' . $patientObj->barCode . ' в ЦОД неактивна, а/к ' . $patientObj->numberHistory); return 'Номер карты рецептов пациента не активен. Уточните актуальный номер.'; } $valueId = $this->xml_attribute($this->getXmlNode($DPCPatient, 'reference'), 'value'); if (!$patientObj->isLocal && !empty($valueId) && $patientObj->isMainRegistration) { $patientObj->enterpriseGUID = substr($valueId, 13); $this->initPatientXMLbase($patientObj); $this->dpcUpdatePatient($patientObj); } } } } } $this->deActivatePatientsByPIN($patientObj); return true; } } private function addNewPatient($patientObj) { $DPCPatient = $this->getDPCPatientByBarCode($patientObj); if ($DPCPatient) { $DPCPatient = new SimpleXMLElement($DPCPatient); foreach ($DPCPatient->children() as $child) { $valueId = $this->xml_attribute($this->getXmlNode($child, 'id'), 'value'); $valueVersionId = $this->xml_attribute($this->getXmlNode($child, 'versionId'), 'value'); if ($valueId && $valueVersionId) { break; } } if (!empty($valueId) && !empty($valueVersionId)) { $patientObj->GUID = $valueId; $patientObj->versionGUID = $valueVersionId; $this->checkManagingOrganizationUpdate($patientObj, $DPCPatient); } else { if (!empty($patientObj->PIN)) { $DPCPatient = $this->getDPCPatientByPIN($patientObj); if ($DPCPatient) { $DPCPatient = new SimpleXMLElement($DPCPatient); foreach ($DPCPatient->children() as $child) { $valueId = $this->xml_attribute($this->getXmlNode($child, 'id'), 'value'); $valueVersionId = $this->xml_attribute($this->getXmlNode($child, 'versionId'), 'value'); if ($valueId && $valueVersionId) { break; } if (!empty($valueId) && !empty($valueVersionId)) { $patientObj->GUID = $valueId; $patientObj->versionGUID = $valueVersionId; $this->checkManagingOrganizationUpdate($patientObj, $DPCPatient); } else { $this->log('ошибка при поиске в ЦОД пациента, а/к ' . $patientObj->numberHistory); $newPatient = $this->addDPCPatient(); if ($newPatient) { $newPatient = new SimpleXMLElement($newPatient); $patientObj->GUID = $this->xml_attribute($this->getXmlNode($newPatient, 'id'), 'value'); if (!empty($patientObj->GUID)) { $this->dbUpdatePatientGUID($patientObj); } else { $this->log('ошибка при поиске в ЦОД пациента, а/к ' . $patientObj->numberHistory); } } } } } } } } } private function createPatientObj($patientCode) { $dbPatient = $this->getPatient($patientCode); if ($dbPatient) { try { $patient = new stdClass; $patient->id = isEmptyProperty($dbPatient, 'medPatientCode'); $patient->GUID = isEmptyProperty($dbPatient, 'GUID'); $patient->PIN = isEmptyProperty($dbPatient, 'personalNumber'); $patient->surname = isEmptyProperty($dbPatient, 'surname'); $patient->name = isEmptyProperty($dbPatient, 'name'); $patient->secondName = isEmptyProperty($dbPatient, 'secondName'); $patient->barCode = isEmptyProperty($dbPatient, 'barCode'); $patient->sex = isEmptyProperty($dbPatient, 'sex'); $patient->barState = isEmptyProperty($dbPatient, 'medPatientBarState'); $patient->state = isEmptyProperty($dbPatient, 'medPatientState'); $patient->dateOfBirth = isEmptyProperty($dbPatient, 'dateOfBirth'); $patient->numberHistory = isEmp